package org.apache.commons.codec.binary;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import java.nio.ByteBuffer;
import java.nio.CharBuffer;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class StringUtils_ESTest_test06 extends StringUtils_ESTest_scaffolding {

    /**
     * The character sequence used by the original generated test. It is an arbitrary
     * string in which every visible character is immediately followed by a NUL
     * ('�') character, e.g. '[' , NUL , 'N' , NUL , ... , 'W' , NUL.
     *
     * <p>It is built here from plain ASCII source (a visible character plus an explicit
     * NUL) so the test file contains no embedded control characters, while the resulting
     * runtime string is identical to the literal in the original test.</p>
     */
    private static String buildNulSeparatedText() {
        String visibleChars = "[NQ.38g~9u=YGOxnW";
        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < visibleChars.length(); i++) {
            builder.append(visibleChars.charAt(i)).append((char) 0);
        }
        return builder.toString();
    }

    /**
     * Verifies that {@link StringUtils#equals(CharSequence, CharSequence)} returns
     * {@code true} when comparing a {@code String} against a {@code CharBuffer} that
     * wraps the exact same characters.
     *
     * <p>Because the two arguments are different CharSequence implementations (not both
     * {@code String}s), {@code equals} falls back to a length plus per-region character
     * comparison, which still reports them as equal.</p>
     */
    @Test(timeout = 4000)
    public void equalsReturnsTrueForStringAndMatchingCharBuffer() throws Throwable {
        String text = buildNulSeparatedText();
        CharBuffer sameCharsAsBuffer = CharBuffer.wrap((CharSequence) text);

        boolean areEqual = StringUtils.equals((CharSequence) text, (CharSequence) sameCharsAsBuffer);

        assertTrue(areEqual);
    }
}
